// -----------------------------------------------------------------------
// EDIT THIS: your real, factual background. The prompt is explicitly told
// never to invent anything outside this block - that is the hallucination guard.
// -----------------------------------------------------------------------
const FACTS = `
Name: Rakshith G
Role: Software engineer (full-stack and AI). B.E. in Electronics and Communication, Global Academy of Technology, 2021-2025, CGPA 7.12.
Experience:
- Analyst, EY (Mar 2026 - Oct 2026): built onboarding and payout workflows for a healthcare client's Doctor Payout POC on the Cloud Nine platform; data analysis and reporting for the Jewellery Analyzer engagement; used React and Node.js in a live client setting.
- Freelance Software Developer (May 2025 - Aug 2025): AI-driven tools in Python and JavaScript; backend services and databases for small clients.
- AI Engineer Intern, Excentrix Ventures (Oct 2024 - Jan 2025): ML pipelines with Python, Scikit-learn and TensorFlow; LLM backend services with LangChain; conversational AI and NLP.
- Science Communicator, PARAM Innovation (part-time weekends, Jul 2025 - Apr 2026): explained engineering ideas through live demonstrations.
Projects:
- AI-Powered Recruitment Platform (React, Node.js, Express, Gemini API, MongoDB, Docker, GCP): resume screening, interview scheduling, LLM-generated questions, NLP resume analysis.
- Job Recommendation Agent (FastAPI, Streamlit, LangChain, Gemini API, MongoDB): RAG-based semantic job search.
- Personal Finance Analyzer (React, TypeScript, Node.js, FastAPI, MongoDB): REST APIs, interactive charts, goals, downloadable reports.
- JobPilot (n8n, PostgreSQL, Docker, Telegram API): self-hosted pipeline that ingests about 460 postings, dedupes with fingerprints, scores them deterministically and sends a daily digest.
Skills: Java (core and OOP), Python, JavaScript, TypeScript, React, Node.js, Express, FastAPI, Django, SQL, MySQL, MongoDB, Docker, GCP, Git, Scikit-learn, TensorFlow, NLP, LLMs, LangChain, LangGraph, RAG, FAISS, OpenCV.
Certifications: Data Science using Python (IIT Madras), Artificial Intelligence (Infosys), Git and GitHub (Microsoft), DSA (TUF+).
Limitations: no production Kubernetes; no formal machine-learning degree; no large-scale distributed systems experience; Electronics and Communication background rather than Computer Science.
`.trim();

const job = $input.first().json;
if (!job || job.id === undefined) {
  return [{ json: { empty: true, note: 'No unscored job with score >= 70. Run 01 and 02 first, or lower the threshold.' } }];
}

const jd = String(job.description || '').slice(0, 4000);
const keywords = (job.matched_keywords || []).slice(0, 8).join(', ');

const system =
  'You write short, specific cover letters. Rules: (1) use ONLY facts from the CANDIDATE block, ' +
  '(2) never invent employers, degrees, metrics or skills, (3) if the candidate lacks something the job asks for, do not claim it, ' +
  '(4) 110-150 words, plain text, no markdown, no greeting placeholder other than "Dear <Company> team", ' +
  '(5) mention at most 3 overlapping technologies, (6) end with one concrete sentence about what the candidate would do in week one, ' +
  '(7) never attach a technology to a project unless that project line in the CANDIDATE block lists it.';

const user =
  'CANDIDATE\n' + FACTS + '\n\nJOB\nTitle: ' + job.title + '\nCompany: ' + job.company + '\nLocation: ' + (job.location || 'n/a') +
  '\nOverlapping keywords detected: ' + (keywords || 'none') + '\n\nJOB DESCRIPTION\n' + jd +
  '\n\nWrite the cover letter now.';

return [{ json: { job_id: Number(job.id), title: job.title, company: job.company, system, user, model: 'openai/gpt-oss-120b' /* Groq retired llama-3.3; gpt-oss is a reasoning model, so the request uses reasoning_effort: low + 1200 tokens */, prompt_version: 'v1' } }];

const text =
  ($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message.content) || '';
const p = $('Build prompt').first().json;
if (!text.trim()) return [{ json: { empty: true, note: 'Model returned nothing. Check the Groq response in the execution log.' } }];

const q = (v) => "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
return [
  {
    json: {
      job_id: p.job_id,
      company: p.company,
      title: p.title,
      letter: text.trim(),
      save_sql:
        "UPDATE jobs SET cover_letter = " + q(text.trim()) + ", status = 'shortlisted', updated_at = now() WHERE id = " + p.job_id + ';',
    },
  },
];

return [
  {
    json: {
      skipped: true,
      reason: 'GROQ_API_KEY is empty, so the AI branch is bypassed on purpose.',
      next: 'Add a free key to .env, restart with docker compose up -d, then run this workflow again.',
    },
  },
];
